import { firebaseSandboxQuery } from './firebase-sandbox-runtime'
import {
  googleDesktopOAuthConfigFromEnv,
  signInWithGoogleViaSystemBrowser
} from './google-oauth'

// Sandboxed harness runs (scripts/drive.mjs, scripts/screenshot.mjs) point the
// whole app at an isolated userData tree. Must land before anything asks
// app.getPath('userData') — config and crash/offline staging derive from it.
if (process.env.FGCNOTE_USER_DATA) {
  app.setPath('userData', process.env.FGCNOTE_USER_DATA)
}

const isDev = !app.isPackaged

let mainWindow: BrowserWindow | null = null
let googleSignInAttempt: { controller: AbortController; promise: Promise<GoogleSignInResult> } | null =
  null

/**
 * The most recent match of live slots against the library.
 *
 * Held here rather than recomputed per request because it is published to the
 * mod at the same moment it is handed to the renderer, and those two must not be
 * able to disagree. See slot-names.ts.
 */
let savedInSlot: SlotMatch = {}
const recordingProjection = new RecordingProjectionStore()

/**
 * Watches the bridge folder for the whole process lifetime.
 *
 * The path is resolved per poll rather than captured here, so changing the game
 * folder takes effect without restarting the monitor.
 */
const monitor = createBridgeMonitor(
  () => resolveBridgePath(),
  () => resolveCoreBridgePath(),
  () => {
    const gamePath = loadConfig().gamePath
    return gamePath !== null && hasInstalledModFiles(gamePath)
  },
  () => republishAndPush()
)

/**
 * Consumes the immutable mod outbox into app-owned durable evidence. It starts
 * only after the repository seam exists: returning persisted/duplicate is the
 * exact point at which observation.ts is allowed to acknowledge an event.
 */
const observationMonitor = createObservationMonitor(
  () => resolveObservationBridgePath(),
  () => {
    const gamePath = loadConfig().gamePath
    return gamePath ? readSf6BuildId(gamePath) : null
  },
  async (observation) => {
    const outcome = persistExecutionObservation(observationRepositoryRoot(), observation)
    // Hydration is repository-driven and idempotent. Pushing here makes a new
    // observation visible to subsequent library reads without renderer input.
    republishAndPush()
    return outcome
  },
  (state) => {
    // Nothing durable depends on this reaching anyone: the drain also runs at
    // startup and after every library load, so a push lost to a closed window
    // costs latency, never evidence.
    if (state.persisted === 0) return
    mainWindow?.webContents.send('observation:staged', {
      persisted: state.persisted,
      at: state.polledAt
    } satisfies ObservationStagingSignal)
  }
)

