/**
 * Launches the packaged renderer, optionally drives it to a surface, and
 * reports what actually rendered.
 *
 * `pnpm run build` (or `build:desktop` from the root) first — this drives
 * `out/`, not the dev server. Then:
 *
 *     node scripts/screenshot.mjs [--flow <name>] [--surface <name>] [--sandbox <dir>] [--full] [output.png]
 *
 * Boots ISOLATED by default (scripts/sandbox.mjs): userData is
 * `<sandbox>/userData` via FGCNOTE_USER_DATA, with config.json pre-seeded to
 * point gamePath at the sandbox's fake game folder — the run touches nothing
 * the user owns, and their app/game can be open concurrently. Pass
 * `--sandbox <dir>` to attach to a root something else populated (a mock-mod
 * publishing live state, a Firebase fixture run); omit it for a fresh empty one.
 * `--real` boots against the real userData and game, the old behaviour.
 *
 * Surface names (they match UI-VOCABULARY.md):
 *
 *     dummy | library | drills | progress | settings | task-editor
 *
 * Two ways to get there, for two different questions:
 *
 *   --flow <name>     Clicks its way there through the real UI after boot —
 *                     tab buttons, the settings gear, Drills' New-drill
 *                     button. Use it when the navigation itself is part of
 *                     what you want verified. A step that cannot run (button
 *                     hidden by a takeover, disabled for want of a live
 *                     character) is reported and the screenshot still taken —
 *                     the state it got stuck in is the evidence.
 *
 *   --surface <name>  Boots the app already on that surface, via the
 *                     FGCNOTE_DEBUG_SURFACE env var (validated in preload,
 *                     seeds only the shell's initial state — see App.tsx).
 *                     Use it when you just want to look at the destination.
 *                     'task-editor' still needs a live character in the
 *                     bridge snapshot, same as the real entry point.
 *
 * `--full` captures the whole scrollable page instead of just the viewport.
 * The default is the viewport on purpose — it is what the user actually sees,
 * which is the honest artifact for judging a layout. Reach for `--full` when
 * the question is about content rather than first impression, or when handing
 * the shot to someone (or something) that would otherwise invent complaints
 * about the part below the fold.
 *
 * With neither flag it behaves as before: boot, wait for the tab bar, report.
 * In every mode it prints the visible tabs, headings and a handful of computed
 * styles (proof the token bridge resolved at runtime), saves a screenshot, and
 * lists every console error/warning/pageerror the page produced. Exists because
 * two whole classes of bug are invisible to typecheck and to the dev server:
 * CSP violations only the packaged build trips over, and `app://` asset paths
 * that resolve fine under Vite and 404 in production.
 *
 * Needs `playwright-core`, which is a desktop dev dependency because pnpm keeps
 * workspace dependency boundaries strict instead of exposing the web app's
 * transitive copy here.
 */
import { createRequire } from 'node:module'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import { ensureSandbox, freshSandboxRoot, sandboxFirebaseEnv } from './sandbox.mjs'

const APP_DIR = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')

const TAB_INDEX = { dummy: 0, library: 1, drills: 2, progress: 3 }
// engine-dev is the dev-only DistanceBandEditor harness (views/EngineDev.tsx);
// it renders no tab bar, which --surface already tolerates.
const SURFACES = [...Object.keys(TAB_INDEX), 'account-gate', 'settings', 'task-editor', 'engine-dev']

let flow = null
let surface = null
let fullPage = false
let shot = 'screenshot.png'
let sandboxRoot = null
let real = false
{
  const args = process.argv.slice(2)
  for (let i = 0; i < args.length; i += 1) {
    if (args[i] === '--flow') flow = args[++i]
    else if (args[i] === '--surface') surface = args[++i]
    else if (args[i] === '--full') fullPage = true
    else if (args[i] === '--sandbox') sandboxRoot = path.resolve(args[++i])
    else if (args[i] === '--real') real = true
    else shot = args[i]
  }
  for (const picked of [flow, surface]) {
    if (picked !== null && !SURFACES.includes(picked)) {
      console.error(`unknown surface "${picked}" — one of: ${SURFACES.join(' | ')}`)
      process.exit(2)
    }
  }
  if (real && sandboxRoot) {
    console.error('--real and --sandbox are mutually exclusive')
    process.exit(2)
  }
}

let sandbox = null
if (!real) {
  if (!sandboxRoot) sandboxRoot = freshSandboxRoot()
  sandbox = ensureSandbox(sandboxRoot)
  console.log(`sandbox: ${sandboxRoot}`)
}

const require = createRequire(path.join(APP_DIR, 'package.json'))

let electron
try {
  // eslint-disable-next-line no-underscore-dangle
  electron = require('playwright-core')._electron
} catch {
  console.error('playwright-core is not installed. Run `pnpm install` from the repo root.')
  process.exit(1)
}

// Same trick scripts/run-electron-vite.mjs plays: VS Code exports
// ELECTRON_RUN_AS_NODE into its terminal, which makes the Electron binary boot
// as plain Node and die on the first line of main/index.ts.
const env = { ...process.env }
delete env.ELECTRON_RUN_AS_NODE
delete env.ELECTRON_NO_ATTACH_CONSOLE
if (surface) env.FGCNOTE_DEBUG_SURFACE = surface
if (sandbox) {
  env.FGCNOTE_USER_DATA = sandbox.userData
  Object.assign(env, sandboxFirebaseEnv(sandbox, env))
}

const app = await electron.launch({
  executablePath: require('electron'),
  args: ['.'],
  cwd: APP_DIR,
  env,
  timeout: 60_000
})

const page = await app.firstWindow()

const problems = []
page.on('console', (msg) => {
  const kind = msg.type()
  if (kind === 'error' || kind === 'warning') problems.push(`[${kind}] ${msg.text()}`)
})
page.on('pageerror', (error) => problems.push(`[pageerror] ${error.message}`))

// The boot chain is a handful of awaited IPC round trips; wait for the tab bar
// rather than guessing a delay. (Under --surface the destination may be a
// takeover that never shows one — that is not a failure there.)
await page.waitForLoadState('domcontentloaded')
try {
  await page.waitForFunction(() => !!document.querySelector('nav button'), null, {
    timeout: 20_000
  })
} catch {
  if (!surface) console.log('!! tab bar never appeared')
}
await new Promise((resolve) => setTimeout(resolve, 2_500))

/**
 * Clicks to `name` through the real UI. Selectors lean on structure rather
 * than text so the locale cannot break them: tabs by position in the nav
 * (their order is fixed in App.tsx), the gear as the only header button with
 * aria-pressed, New drill as the first button of Drills' heading section.
 */
async function runFlow(name) {
  const clickTab = async (id) => {
    const nav = page.locator('nav button')
    if ((await nav.count()) === 0) {
      problems.push(`[flow] no tab bar — a takeover owns the window, cannot reach ${id}`)
      return false
    }
    await nav.nth(TAB_INDEX[id]).click()
    return true
  }

  if (name in TAB_INDEX) return clickTab(name)

  if (name === 'settings') {
    const gear = page.locator('header button[aria-pressed]')
    if ((await gear.count()) === 0) {
      problems.push('[flow] settings gear not visible — a takeover owns the window')
      return false
    }
    await gear.click()
    return true
  }

  // task-editor: Drills tab, then its New-drill (slot kind) button.
  if (!(await clickTab('drills'))) return false
  const newDrill = page.locator('main section').first().locator('button').first()
  if ((await newDrill.count()) === 0) {
    problems.push('[flow] New drill button not found on Drills')
    return false
  }
  if (await newDrill.isDisabled()) {
    problems.push('[flow] New drill is disabled — no live character in the bridge snapshot')
    return false
  }
  await newDrill.click()
  return true
}

if (flow) {
  await runFlow(flow)
  // Surfaces render synchronously off local state; one beat for layout/fonts.
  await new Promise((resolve) => setTimeout(resolve, 800))
}

const seen = await page.evaluate(() => ({
  title: document.title,
  tabs: [...document.querySelectorAll('nav button')].map((b) => b.textContent.trim()),
  headings: [...document.querySelectorAll('h2')].map((h) => h.textContent.trim()),
  dialogs: [...document.querySelectorAll('dialog[open], [role="dialog"]')].length,
  locale: document.querySelector('select')?.value ?? null,
  bodyLength: document.body.innerText.length,
  computed: {
    bodyBg: getComputedStyle(document.body).backgroundColor,
    bodyFont: getComputedStyle(document.body).fontFamily.slice(0, 40),
    navBg: document.querySelector('nav')
      ? getComputedStyle(document.querySelector('nav')).backgroundColor
      : null
  }
}))

console.log(JSON.stringify(seen, null, 2))
await page.screenshot({ path: shot, fullPage })
console.log('screenshot:', path.resolve(shot), fullPage ? '(full page)' : '(viewport)')
console.log(`--- console problems (${problems.length}) ---`)
for (const problem of problems.slice(0, 25)) console.log(problem)

await app.close()
process.exit(problems.length > 0 ? 1 : 0)

/**
 * The sandbox: one disposable folder standing in for BOTH kinds of real
 * state — the app's userData and the game folder — so a scripted run
 * (mock-mod + drive/screenshot/firebase fixture) touches nothing the user owns.
 *
 *     <root>/
 *       userData/   isolated Electron userData (FGCNOTE_USER_DATA); its
 *                   config.json is pre-seeded with gamePath → <root>/game,
 *                   which is load-bearing: with gamePath null the app's
 *                   loadConfig() auto-detects the REAL SF6 install via Steam
 *                   (config.ts) and the isolation is silently punctured.
 *       game/       fake game folder; the fgcnote bridge trees under
 *                   reframework/data/, same relative layout as the mod's.
 *                   Empty autorun entry/Core markers make the runtime presence
 *                   check agree with the mock's fresh health beat.
 *       control/    mock-mod's player-event channel (drive's `game` steps).
 *
 * The root is chosen by the CALLER: two processes cooperate by being handed
 * the same `--sandbox` path — there is no fixed shared location and no
 * discovery mechanism, so concurrent runs cannot collide by construction.
 * A script run without `--sandbox` mints a fresh root (and prints it); an
 * orchestrator (the ux-loop skill) mints one per round and passes it to
 * every script in that round.
 */
import { randomUUID } from 'node:crypto'
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import os from 'node:os'
import path from 'node:path'

const FGCNOTE_RELATIVE = path.join('reframework', 'data', 'fgcnote')

/** A root no other run can be using: timestamp + pid. */
export function freshSandboxRoot() {
  const stamp = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19)
  return path.join(os.tmpdir(), 'fgcnote-sandbox', `${stamp}-${process.pid}-${randomUUID()}`)
}

/** The layout, resolved but not created. */
export function sandboxPaths(root) {
  const game = path.join(root, 'game')
  const fgcnote = path.join(game, FGCNOTE_RELATIVE)
  return {
    root,
    userData: path.join(root, 'userData'),
    firebaseIdentity: path.join(root, 'firebase-identity.json'),
    game,
    control: path.join(root, 'control'),
    bridge: path.join(fgcnote, 'training'),
    core: path.join(fgcnote, 'core'),
    task: path.join(fgcnote, 'task'),
    observations: path.join(fgcnote, 'observations')
  }
}

/**
 * Create the layout (idempotent) and return it. config.json is only written
 * when absent, so a second script attaching to the same sandbox — or a rerun
 * against a kept one — never clobbers state the app wrote meanwhile.
 */
export function ensureSandbox(root) {
  const paths = sandboxPaths(root)
  for (const dir of [
    paths.userData,
    paths.bridge,
    paths.core,
    paths.task,
    path.join(paths.observations, 'events'),
    paths.control
  ]) {
    mkdirSync(dir, { recursive: true })
  }
  const configFile = path.join(paths.userData, 'config.json')
  if (!existsSync(configFile)) {
    writeFileSync(
      configFile,
      JSON.stringify({ gamePath: paths.game, gamePathSource: 'manual' }, null, 2),
      'utf-8'
    )
  }
  // The install marker hasReframework() (config.ts) looks for. Without it the
  // app boots into the SetupWizard takeover — no tab bar, nothing drivable.
  // The sandbox impersonates a machine where game + loader + mod are all
  // installed, the same way mock-mod impersonates the mod's runtime.
  const loaderMarker = path.join(paths.game, 'dinput8.dll')
  if (!existsSync(loaderMarker)) writeFileSync(loaderMarker, '')
  const autorunRoot = path.join(paths.game, 'reframework', 'autorun')
  const moduleRoot = path.join(autorunRoot, 'fgcnote')
  mkdirSync(moduleRoot, { recursive: true })
  for (const marker of [path.join(autorunRoot, 'fgcnote.lua'), path.join(moduleRoot, 'Core.lua')]) {
    if (!existsSync(marker)) writeFileSync(marker, '-- mock-mod sandbox marker\n')
  }
  let firebaseUid
  if (existsSync(paths.firebaseIdentity)) {
    const identity = JSON.parse(readFileSync(paths.firebaseIdentity, 'utf-8'))
    if (identity.version !== 1 || typeof identity.uid !== 'string' || !identity.uid) {
      throw new Error(`Invalid sandbox Firebase identity: ${paths.firebaseIdentity}`)
    }
    firebaseUid = identity.uid
  } else {
    firebaseUid = `sandbox-${randomUUID()}`
    writeFileSync(
      paths.firebaseIdentity,
      JSON.stringify({ version: 1, uid: firebaseUid }, null, 2) + '\n',
      { encoding: 'utf-8', flag: 'wx' }
    )
  }
  return { ...paths, firebaseUid }
}

/** Runtime-only Firebase settings shared by every app launch for this sandbox. */
export function sandboxFirebaseEnv(sandbox, env = process.env) {
  return {
    FGCNOTE_FIREBASE_SANDBOX: 'true',
    FGCNOTE_FIREBASE_SANDBOX_UID: sandbox.firebaseUid,
    FGCNOTE_FIREBASE_EMULATOR_HOST: env.FGCNOTE_FIREBASE_EMULATOR_HOST ?? '127.0.0.1',
    FGCNOTE_FIREBASE_AUTH_EMULATOR_PORT: env.FGCNOTE_FIREBASE_AUTH_EMULATOR_PORT ?? '9099',
    FGCNOTE_FIREBASE_FIRESTORE_EMULATOR_PORT:
      env.FGCNOTE_FIREBASE_FIRESTORE_EMULATOR_PORT ?? '8080'
  }
}

/**
 * Drives the packaged app through a scripted flow — screenshot, act,
 * screenshot — producing the step-annotated evidence bundle a UX judge (or a
 * human) reads. The interactive half of the loop that screenshot.mjs's
 * one-shot capture cannot provide.
 *
 *     node scripts/drive.mjs --flow <file.json> [--sandbox <dir>] [--out <dir>]
 *     pnpm run drive -- --flow flows/dummy-goal-a.json
 *
 * ## Sandbox by default — the real app state is opt-in
 *
 * By default the app boots ISOLATED (scripts/sandbox.mjs): its userData is
 * `<sandbox>/userData` (via FGCNOTE_USER_DATA, main/index.ts) with a
 * pre-seeded config.json whose gamePath points at `<sandbox>/game` — so the
 * run reads and writes nothing the user owns, and the user's own app or game
 * can be open at the same time. Pass `--sandbox <dir>` to attach to the root
