  cwd: APP_DIR,
  env,
  detached: true,
  stdio: ['ignore', logFd, logFd]
})

const outcome = await new Promise((resolve) => {
  let settled = false
  const finish = (value) => {
    if (settled) return
    settled = true
    resolve(value)
  }
  child.once('error', (error) => finish({ error }))
  child.once('exit', (code, signal) => finish({ code, signal }))
  child.once('spawn', () => setTimeout(() => finish({ running: true }), 1_000))
})
closeSync(logFd)

if (!('running' in outcome)) {
