    : `exited early (${outcome.signal ?? `code ${outcome.code}`})`
  console.error(`review app failed to stay open: ${detail}`)
  console.error(`log: ${logPath}`)
  process.exit(1)
}

child.unref()
if (sandbox) console.log(`sandbox: ${sandbox.root}`)
console.log(`review app: pid ${child.pid}, label "${label.trim()}"`)
console.log(`log: ${logPath}`)

