mainWindow.once('ready-to-show', () => {
  if (agentWindowMode === 'hidden') return
  if (agentWindowMode === 'review') {
    if (!Notification.isSupported()) {
      console.error('[agent-review] native notifications are unavailable; review window remains hidden')
      return
    }
    reviewNotification = new Notification({
      title: 'FGC Note review is ready',
      body: windowLabel ? `Click to open ${windowLabel}` : 'Click to open the finished app',
      silent: true
    })
    reviewNotification.on('click', () => {
      mainWindow?.show()
      mainWindow?.focus()
    })
    reviewNotification.on('close', () => {
      reviewNotification = null
    })
    reviewNotification.show()
    return
  }
  mainWindow?.show()
})

